// Package jobs runs background work (renewals, webhook deliveries, emails) on a fixed number of workers.
package jobs

import (
	"context"
	"errors"
	"io"
	"log/slog"
	"runtime/debug"
	"sort"
	"sync"
	"time"
)

// Job is one piece of background work.
type Job struct {
	Name string
	Run  func(ctx context.Context) error
}

// ErrQueueFull is returned by Enqueue when the queue has no room.
var ErrQueueFull = errors.New("the job queue is full")

// ErrStopped is returned by Enqueue once Shutdown or Stop has been called.
var ErrStopped = errors.New("the job runner is stopped")

// stopTimeout is how long Stop waits for running jobs before it cancels them.
const stopTimeout = 30 * time.Second

// task is a job on its way through a Runner.
type task struct {
	job       Job
	seq       uint64             // enqueue order
	ctx       context.Context    // set when a worker starts the job
	cancel    context.CancelFunc // set when a worker starts the job
	cancelled bool               // Shutdown cancelled ctx
}

// Runner runs jobs on its workers.
type Runner struct {
	workers  int
	capacity int
	log      *slog.Logger

	mu          sync.Mutex
	cond        *sync.Cond    // signalled when a job is queued or the runner closes
	queue       []*task       // enqueued and not yet started, oldest first
	running     map[*task]bool
	interrupted []*task       // cancelled by Shutdown and returned an error
	seq         uint64
	idle        int           // workers waiting for a job
	live        int           // workers that have not exited
	closed      bool          // Shutdown has been called
	drained     chan struct{} // closed once closed and no worker is left
}

// NewRunner returns a runner with workers workers and room for queueSize waiting jobs. A nil log discards.
func NewRunner(workers, queueSize int, log *slog.Logger) *Runner {
	if workers < 1 {
		workers = 1
	}
	if log == nil {
		log = slog.New(slog.NewTextHandler(io.Discard, nil))
	}
	r := &Runner{
		workers:  workers,
		capacity: queueSize,
		log:      log,
		running:  map[*task]bool{},
		drained:  make(chan struct{}),
	}
	r.cond = sync.NewCond(&r.mu)
	return r
}

// Start starts the workers. It does nothing once the runner is shut down.
func (r *Runner) Start() {
	r.mu.Lock()
	defer r.mu.Unlock()
	if r.closed {
		return
	}
	for i := 0; i < r.workers; i++ {
		r.live++
		go r.work()
	}
}

func (r *Runner) work() {
	defer func() {
		r.mu.Lock()
		r.live--
		r.drainLocked()
		r.mu.Unlock()
	}()
	for {
		t, ok := r.next()
		if !ok {
			return
		}
		r.run(t)
	}
}

// next waits for a queued job and marks it running. It returns false once the runner is closed.
func (r *Runner) next() (*task, bool) {
	r.mu.Lock()
	defer r.mu.Unlock()
	r.idle++
	for len(r.queue) == 0 && !r.closed {
		r.cond.Wait()
	}
	r.idle--
	if r.closed {
		return nil, false
	}
	t := r.queue[0]
	r.queue[0] = nil
	r.queue = r.queue[1:]
	t.ctx, t.cancel = context.WithCancel(context.Background())
	r.running[t] = true
	return t, true
}

// run runs t's job and records it as interrupted when Shutdown cancelled it and it returned an error.
func (r *Runner) run(t *task) {
	panicked, err := r.call(t)
	r.mu.Lock()
	delete(r.running, t)
	if err != nil && !panicked && t.cancelled {
		r.interrupted = append(r.interrupted, t)
	}
	r.mu.Unlock()
	t.cancel()
	if err != nil {
		r.log.Error("job failed", "job", t.job.Name, "err", err)
	}
}

// call runs t's job and recovers a panic. It reports whether the job panicked and the error it returned.
func (r *Runner) call(t *task) (panicked bool, err error) {
	defer func() {
		if p := recover(); p != nil {
			r.log.Error("job panicked", "job", t.job.Name, "panic", p, "stack", string(debug.Stack()))
			panicked = true
		}
	}()
	return false, t.job.Run(t.ctx)
}

// drainLocked closes drained once the runner is closed and no worker is left. Call it with mu held.
func (r *Runner) drainLocked() {
	if r.closed && r.live == 0 {
		close(r.drained)
	}
}

// Enqueue adds a job to the queue without waiting. It returns ErrQueueFull when the queue has no room,
// and ErrStopped once Shutdown has been called.
func (r *Runner) Enqueue(j Job) error {
	r.mu.Lock()
	defer r.mu.Unlock()
	if r.closed {
		return ErrStopped
	}
	// An idle worker takes a job at once, so it has room even when the queue has none.
	if len(r.queue) >= r.capacity+r.idle {
		return ErrQueueFull
	}
	r.seq++
	r.queue = append(r.queue, &task{job: j, seq: r.seq})
	r.cond.Signal()
	return nil
}

// Shutdown stops the runner. From the moment it is called, Enqueue returns ErrStopped and jobs that have not
// started are not started. It waits for running jobs to finish. If ctx ends first, it cancels the context of
// every running job, waits for them to return, and returns ctx.Err(). Otherwise it returns nil.
//
// Calls after the first return nil at once without waiting.
func (r *Runner) Shutdown(ctx context.Context) error {
	r.mu.Lock()
	if r.closed {
		r.mu.Unlock()
		return nil
	}
	r.closed = true
	r.cond.Broadcast()
	r.drainLocked()
	r.mu.Unlock()

	select {
	case <-r.drained:
		return nil
	case <-ctx.Done():
	}

	r.mu.Lock()
	select {
	case <-r.drained: // every job finished just as ctx ended
		r.mu.Unlock()
		return nil
	default:
	}
	for t := range r.running {
		t.cancelled = true
		t.cancel()
	}
	r.mu.Unlock()

	<-r.drained
	return ctx.Err()
}

// Stop shuts the runner down like Shutdown, waiting up to 30 seconds for running jobs before it cancels them.
func (r *Runner) Stop() {
	ctx, cancel := context.WithTimeout(context.Background(), stopTimeout)
	defer cancel()
	_ = r.Shutdown(ctx)
}

// Pending returns the jobs that still need to run, in enqueue order. Before Shutdown these are the queued jobs.
// After Shutdown they are the jobs that were never started, followed by the jobs whose context Shutdown
// cancelled and that returned an error.
func (r *Runner) Pending() []Job {
	r.mu.Lock()
	defer r.mu.Unlock()
	sort.Slice(r.interrupted, func(i, j int) bool { return r.interrupted[i].seq < r.interrupted[j].seq })
	out := make([]Job, 0, len(r.queue)+len(r.interrupted))
	for _, t := range r.queue {
		out = append(out, t.job)
	}
	for _, t := range r.interrupted {
		out = append(out, t.job)
	}
	return out
}

